def price(name, cat, stars=0, bib=False):
    n=name
    if n in OVER: return OVER[n]
    base=n.split(' (')[0].split(' / ')[0].strip()
    if base in OVER: return OVER[base]
    if stars>=2: return 4
    if stars==1: return 3
    if bib: return 2
    return CAT_DEFAULT.get(cat,2)
def band(n): return '$'*n
